<script>
    function SafeGetValue(obj, path, defaultValue = "N/A") {
        if (!path) return defaultValue;
        const keys = path.split('.');
        let current = obj;
        for (const key of keys) {
            if (current === null || typeof current !== 'object' || !current.hasOwnProperty(key)) {
                return defaultValue;
            }
            current = current[key];
        }
        return current === null || current === undefined ? defaultValue : current;
    }

    function toggleSection(element) {
        const content = element.nextElementSibling;
        if (!content) return;
        const isExpanded = content.classList.toggle('expanded');
        element.classList.toggle('expanded-header', isExpanded);
        const arrow = element.querySelector('span:last-child');
        if (arrow) arrow.innerText = isExpanded ? '▲' : '▼';
    }

    function changePage(tabElement, pageId) {
        document.querySelectorAll('.tab').forEach(tab => tab.classList.remove('active-tab'));
        tabElement.classList.add('active-tab');
        document.querySelectorAll('.page').forEach(page => page.classList.remove('active-page'));
        document.getElementById(pageId).classList.add('active-page');
    }

    function getValueFromArray(data) {
        if (Array.isArray(data)) {
            return data[0];
        }
        return data; // Return as is if not an array
    }

    function setTextContent(id, value) {
        const el = document.getElementById(id);
        if (el) el.textContent = getValueFromArray(value);
    }

    function setStatusClass(id, valueStr) {
        const el = document.getElementById(id);
        if (!el) return;

        el.classList.remove('status-fine', 'status-warning', 'status-danger');

        const testStr = String(valueStr).toLowerCase();

        if (testStr.includes('完好') || testStr.includes('健康')) {
            el.classList.add('status-fine');
        } else if (testStr.includes('轻伤') || testStr.includes('中度')) {
            el.classList.add('status-warning');
        } else if (testStr.includes('重度') || testStr.includes('残废') || testStr.includes('感染') || testStr.includes('中毒')) {
            el.classList.add('status-danger');
        }
    }

    function updateProgressBar(barId, valueId, value, max = 100) {
        const progressBar = document.getElementById(barId);
        const valueDisplay = document.getElementById(valueId);
        const displayValue = getValueFromArray(value);
        if (valueDisplay) valueDisplay.innerText = `${displayValue} / ${max}`;
        if (progressBar) {
            const numericValue = parseInt(displayValue, 10) || 0;
            const percentage = max > 0 ? (numericValue / max) * 100 : 0;
            progressBar.style.width = `${Math.max(0, Math.min(100, percentage))}%`;
        }
    }

    function updateStatusData(characterData, fullGameData) {
        if (!characterData || !fullGameData) return;

        // 概览 - 世界
        setTextContent('world-date', SafeGetValue(characterData, '世界状态.日期'));
        setTextContent('world-time', SafeGetValue(characterData, '世界状态.时间'));
        setTextContent('world-location', SafeGetValue(characterData, '世界状态.当前位置'));
        setTextContent('world-weather', SafeGetValue(characterData, '世界状态.天气'));

        // 概览 - 核心生理
        updateProgressBar('phys-hunger-bar', 'phys-hunger', SafeGetValue(characterData, '生理状态.饱食度'));
        updateProgressBar('phys-thirst-bar', 'phys-thirst', SafeGetValue(characterData, '生理状态.饮水度'));
        updateProgressBar('phys-stamina-bar', 'phys-stamina', SafeGetValue(characterData, '生理状态.精力'));
        updateProgressBar('phys-sanity-bar', 'phys-sanity', SafeGetValue(characterData, '生理状态.理智'));

        // 概览 - 其他状态
        setTextContent('phys-mood', SafeGetValue(characterData, '生理状态.心情'));
        setTextContent('phys-temp', getValueFromArray(SafeGetValue(characterData, '生理状态.体温')) + ' °C');
        setTextContent('phys-wetness', SafeGetValue(characterData, '生理状态.身体潮湿度'));
        setTextContent('phys-hygiene', SafeGetValue(characterData, '生理状态.卫生度'));
        const currentLoad = getValueFromArray(SafeGetValue(characterData, '负重.当前负重'));
        const maxLoad = getValueFromArray(SafeGetValue(characterData, '负重.最大负重'));
        setTextContent('load-current', `${currentLoad} / ${maxLoad}`);

        // 服装
        setTextContent('equip-hat', SafeGetValue(characterData, '服装.帽子'));
        setTextContent('equip-glasses', SafeGetValue(characterData, '服装.眼镜'));
        setTextContent('equip-underwear-top', SafeGetValue(characterData, '服装.上身内层'));
        setTextContent('equip-shirt', SafeGetValue(characterData, '服装.上身外层'));
        setTextContent('equip-coat', SafeGetValue(characterData, '服装.外套'));
        setTextContent('equip-underwear-bottom', SafeGetValue(characterData, '服装.下身内层'));
        setTextContent('equip-pants', SafeGetValue(characterData, '服装.裤子'));
        setTextContent('equip-gloves', SafeGetValue(characterData, '服装.手套'));
        setTextContent('equip-socks', SafeGetValue(characterData, '服装.袜子'));
        setTextContent('equip-shoes', SafeGetValue(characterData, '服装.鞋子'));
        setTextContent('equip-backpack', SafeGetValue(characterData, '服装.背包'));

        // 身体
        const healthStatus = getValueFromArray(SafeGetValue(characterData, '身体状况.健康状态'));
        setTextContent('health-status', healthStatus);
        setStatusClass('health-status', healthStatus);

        const bodyParts = ['head', 'torso', 'arm-left', 'arm-right', 'leg-left', 'leg-right'];
        const bodyPaths = ['头部状态', '躯干状态', '左臂状态', '右臂状态', '左腿状态', '右腿状态'];
        bodyParts.forEach((part, index) => {
            const status = getValueFromArray(SafeGetValue(characterData, `身体状况.${bodyPaths[index]}`));
            setTextContent(`body-${part}`, status);
            setStatusClass(`body-${part}`, status);
        });

        // 物品 (使用 stat_data)
        const inventoryList = document.getElementById('inventory-list');
        inventoryList.innerHTML = '';
        const itemsObject = getValueFromArray(SafeGetValue(fullGameData.stat_data, '物品栏.物品', {}));
        const itemEntries = Object.entries(itemsObject).filter(([key]) => key !== '$meta');
        if (itemEntries.length > 0) {
            for (const [name, quantity] of itemEntries) {
                const li = document.createElement('li');
                li.className = 'property';
                const displayValue = (typeof quantity === 'number' || !isNaN(parseInt(quantity, 10))) ? `×${getValueFromArray(quantity)}` : getValueFromArray(quantity);
                li.innerHTML = `<span class="property-name">${name}</span><span class="property-value">${displayValue}</span>`;
                inventoryList.appendChild(li);
            }
        } else {
            inventoryList.innerHTML = '<li class="property"><span class="property-value" style="text-align:center; width: 100%;">空空如也</span></li>';
        }

        // 任务 (使用 characterData)
        const questListContainer = document.getElementById('quest-list');
        questListContainer.innerHTML = '';
        const questValue = getValueFromArray(SafeGetValue(characterData, '任务'));
        if (questValue && questValue !== 'N/A' && questValue !== '无') {
            questListContainer.innerHTML = `<div class="property property-full"><span class="property-value">${questValue}</span></div>`;
        } else {
            questListContainer.innerHTML = '<div class="property"><span class="property-value" style="text-align:center; width: 100%;">当前没有任务</span></div>';
        }
    }

    async function initDisplay() {
        const container = document.getElementById('status-card-container');
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            const gameData = messages[0].data;
            const characterData = gameData.display_data || gameData.stat_data;

            if (!characterData) {
                 container.innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据: 缺少 characterData。</p>";
                 return;
            }

            updateStatusData(characterData, gameData);

            document.querySelectorAll('.section-header').forEach(header => {
                const content = header.nextElementSibling;
                if (content && !content.classList.contains('expanded')) {
                    content.classList.add('expanded');
                    header.classList.add('expanded-header');
                    const arrow = header.querySelector('span:last-child');
                    if (arrow) arrow.innerText = '▲';
                }
            });

        } catch (error) {
            container.innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p>`;
            console.error(error);
        }
    }

    document.addEventListener('DOMContentLoaded', initDisplay);
</script>

</body>
</html>
